import{c as a,Q as t,j as o,m as r}from"./chunks/framework.W-g_WCNV.js";const h=JSON.parse('{"title":"Custom claims","description":"Inject extra fields into OIDC tokens on a per-client basis.","frontmatter":{"title":"Custom claims","description":"Inject extra fields into OIDC tokens on a per-client basis."},"headers":[],"relativePath":"admin/custom-claims.md","filePath":"admin/custom-claims.md"}'),i={name:"admin/custom-claims.md"};function s(n,e,l,d,c,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="custom-claims" tabindex="-1">Custom claims <a class="header-anchor" href="#custom-claims" aria-label="Permalink to &quot;Custom claims&quot;">​</a></h1><p>GateKeeper can inject additional claims (token fields) into access and ID tokens for specific OIDC clients. This lets you pass user attributes to apps that expect non-standard fields without changing how other clients work.</p><p>Manage custom claims at <strong>Admin - OIDC Clients</strong> - click the claims icon next to any client.</p><h2 id="value-sources" tabindex="-1">Value sources <a class="header-anchor" href="#value-sources" aria-label="Permalink to &quot;Value sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Token value</th></tr></thead><tbody><tr><td>User ID</td><td>The user&#39;s internal UUID (<code>sub</code> value)</td></tr><tr><td>Email</td><td>The user&#39;s email address</td></tr><tr><td>Display name</td><td>The user&#39;s display name, or empty if not set</td></tr><tr><td>Groups array</td><td>An array of the user&#39;s group names (same as the built-in <code>groups</code> claim, but under a different key)</td></tr><tr><td>Literal value</td><td>A fixed string you type in - same for every user</td></tr></tbody></table><h2 id="adding-a-claim" tabindex="-1">Adding a claim <a class="header-anchor" href="#adding-a-claim" aria-label="Permalink to &quot;Adding a claim&quot;">​</a></h2><ol><li>Open the claims page for a client.</li><li>Enter a <strong>claim key</strong> - the field name that will appear in the token (letters, digits, underscores only).</li><li>Select a <strong>value source</strong>.</li><li>For literal values, type the static string.</li><li>Click <strong>Add</strong>.</li></ol><p>The claim appears immediately in the next token issued for that client.</p><h2 id="reserved-keys" tabindex="-1">Reserved keys <a class="header-anchor" href="#reserved-keys" aria-label="Permalink to &quot;Reserved keys&quot;">​</a></h2><p>The following keys are reserved by the OIDC spec and cannot be overridden: <code>sub</code>, <code>iss</code>, <code>aud</code>, <code>exp</code>, <code>iat</code>, <code>auth_time</code>, <code>nonce</code>, <code>acr</code>, <code>amr</code>, <code>azp</code>, <code>at_hash</code>, <code>c_hash</code>, <code>jti</code>.</p><h2 id="example-grafana-role-mapping" tabindex="-1">Example - Grafana role mapping <a class="header-anchor" href="#example-grafana-role-mapping" aria-label="Permalink to &quot;Example - Grafana role mapping&quot;">​</a></h2><p>Grafana can map an OIDC claim to its role system. Add a claim with key <code>role</code> and value source <strong>Literal value</strong> set to <code>Viewer</code> to give all users the Viewer role by default. Or use <strong>Groups array</strong> under a custom key if you want Grafana to map group names to roles.</p><h2 id="example-authelia" tabindex="-1">Example - Authelia <a class="header-anchor" href="#example-authelia" aria-label="Permalink to &quot;Example - Authelia&quot;">​</a></h2><p>Authelia&#39;s OIDC authorization policy can match on arbitrary claims. Add a claim with key <code>department</code> and source <strong>Literal value</strong> or pull it from the display name depending on your naming convention.</p>',14)])])}const p=a(i,[["render",s]]);export{h as __pageData,p as default};
